import { Inject, Injectable, InjectionToken, Type, Optional } from '@angular/core';
import { ReportParameterWindowComponent } from './report-parameter-window.component';
import { ReportParameterWindowId } from './report-parameter-window-id';

export interface ReportParameterWindowRegistration {
  id: ReportParameterWindowId;
  component: Type<ReportParameterWindowComponent>;
}

export const MESIX_REPORT_PARAMETER_WINDOWS = new InjectionToken<ReportParameterWindowRegistration[]>(
  'MESIX_REPORT_PARAMETER_WINDOWS',
);

@Injectable({ providedIn: 'root' })
export class ReportParameterWindowRegistry {
  private readonly windows = new Map<ReportParameterWindowId, Type<ReportParameterWindowComponent>>();

  constructor(@Optional() @Inject(MESIX_REPORT_PARAMETER_WINDOWS) registrations: ReportParameterWindowRegistration[] | null) {
    for (const registration of registrations || []) this.register(registration.id, registration.component);
  }

  register(id: ReportParameterWindowId, component: Type<ReportParameterWindowComponent>): void {
    if (this.windows.has(id)) throw new Error(`A report parameter window is already registered for "${id}".`);
    this.windows.set(id, component);
  }

  resolve(id: ReportParameterWindowId): Type<ReportParameterWindowComponent> {
    const component = this.windows.get(id);
    if (!component) throw new Error(`No report parameter window is registered for "${id}".`);
    return component;
  }
}
