import { Directive, EventEmitter, Input, Output } from '@angular/core';

/** Base contract for consumer-owned filter components. */
@Directive()
export abstract class ReportParameterWindowComponent<T extends Record<string, unknown> = Record<string, unknown>> {
  @Input() initialValues: Partial<T> = {};
  @Output() readonly filtersChange = new EventEmitter<T>();

  protected publishFilters(value: T): void { this.filtersChange.emit(value); }
}
