import { Injectable } from '@angular/core';
import { BehaviorSubject } from 'rxjs';
import { ReportColumn, ReportExportContext } from '../reporting.models';
import { ReportExportFormat, ReportExportService } from './report-export.service';

export type ExportState = 'idle' | 'loading' | 'ready' | 'error';
export interface ExportActivity { state: ExportState; reportTitle: string; format: ReportExportFormat | null; progress: number; message: string; blob?: Blob; fileName?: string; }

@Injectable({ providedIn: 'root' })
export class ReportExportActivityService {
  private generation = 0;
  private readonly subject = new BehaviorSubject<ExportActivity>({ state: 'idle', reportTitle: '', format: null, progress: 0, message: '' });
  readonly activity$ = this.subject.asObservable();
  get busy(): boolean { return this.subject.value.state === 'loading'; }

  constructor(private exporter: ReportExportService) {}

  async start<T extends Record<string, unknown>>(title: string, columns: ReportColumn[], format: ReportExportFormat, loadAll: (progress: (count: number) => void) => Promise<T[]>, loadContext: () => Promise<ReportExportContext> = async () => ({ header: [], aggregates: [] })): Promise<void> {
    if (this.busy) throw new Error('Another report export is already in progress.');
    const generation = ++this.generation;
    this.subject.next({ state: 'loading', reportTitle: title, format, progress: 0, message: 'Preparing report…' });
    try {
      const [rows, context] = await Promise.all([loadAll((count) => {
        if (generation === this.generation) this.subject.next({ ...this.subject.value, progress: 0, message: `${count.toLocaleString()} rows loaded` });
      }), loadContext()]);
      if (generation !== this.generation) return;
      this.subject.next({ ...this.subject.value, message: `Creating ${format.toUpperCase()} file…` });
      const blob = await this.exporter.export(title, columns, rows, format, context);
      const fileName = `${this.safeName(title)}-${new Date().toISOString().slice(0, 10)}.${format}`;
      this.subject.next({ ...this.subject.value, state: 'ready', progress: 100, message: `${rows.length.toLocaleString()} rows ready`, blob, fileName });
    } catch (error) {
      if (generation !== this.generation) return;
      this.subject.next({ ...this.subject.value, state: 'error', message: error instanceof Error ? error.message : 'Report export failed.' });
    }
  }

  save(): void {
    const current = this.subject.value;
    if (!current.blob || !current.fileName) return;
    const url = URL.createObjectURL(current.blob);
    const anchor = document.createElement('a'); anchor.href = url; anchor.download = current.fileName; anchor.click();
    setTimeout(() => URL.revokeObjectURL(url), 30_000);
  }

  open(): void {
    const blob = this.subject.value.blob;
    if (blob) {
      const url = URL.createObjectURL(blob);
      window.open(url, '_blank', 'noopener');
      setTimeout(() => URL.revokeObjectURL(url), 60_000);
    }
  }

  dismiss(): void { if (!this.busy) this.subject.next({ state: 'idle', reportTitle: '', format: null, progress: 0, message: '' }); }
  cancelAndDismiss(): void {
    this.generation++;
    this.exporter.cancel();
    this.subject.next({ state: 'idle', reportTitle: '', format: null, progress: 0, message: '' });
  }
  private safeName(value: string): string { return value.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '') || 'report'; }
}
