import { Injectable } from '@angular/core';
import { ReportColumn, ReportExportContext } from '../reporting.models';
import { createReportFile } from './report-export.generator';

export type ReportExportFormat = 'xlsx' | 'docx' | 'pdf';

@Injectable({ providedIn: 'root' })
export class ReportExportService {
  private activeWorker: Worker | null = null;
  private rejectActiveExport?: (reason: Error) => void;

  async export(
    title: string,
    columns: ReportColumn[],
    rows: Record<string, unknown>[],
    format: ReportExportFormat,
    context: ReportExportContext = { header: [], aggregates: [] },
  ): Promise<Blob> {
    if (typeof Worker !== 'undefined') {
      try {
        return await this.exportWithWorker(title, columns, rows, format, context);
      } catch (error) {
        console.warn('Report export worker failed; creating the file in the page instead.', error);
      }
    }
    return createReportFile(title, columns, rows, format, context);
  }

  cancel(): void {
    const reject = this.rejectActiveExport;
    const worker = this.activeWorker;
    this.rejectActiveExport = undefined;
    this.activeWorker = null;
    if (reject) reject(new Error('Report export was cancelled.'));
    else worker?.terminate();
  }

  private exportWithWorker(
    title: string,
    columns: ReportColumn[],
    rows: Record<string, unknown>[],
    format: ReportExportFormat,
    context: ReportExportContext,
  ): Promise<Blob> {
    return new Promise((resolve, reject) => {
      const worker = new Worker(this.workerHref(), { type: 'module' });
      this.activeWorker = worker;
      let settled = false;
      const finish = (error?: Error, blob?: Blob) => {
        if (settled) return;
        settled = true;
        worker.terminate();
        if (this.activeWorker === worker) {
          this.activeWorker = null;
          this.rejectActiveExport = undefined;
        }
        if (error) reject(error);
        else if (blob) resolve(blob);
        else reject(new Error('Could not create the report file.'));
      };
      this.rejectActiveExport = (error) => finish(error);
      worker.onmessage = ({ data }: MessageEvent<{ blob?: Blob; error?: string }>) => {
        data.blob
          ? finish(undefined, data.blob)
          : finish(new Error(data.error || 'Could not create the report file.'));
      };
      worker.onerror = (event) =>
        finish(new Error(event.message || 'Report export worker failed.'));
      worker.onmessageerror = () =>
        finish(new Error('The report export worker returned unreadable data.'));
      try {
        worker.postMessage({ title, columns, rows, format, context });
      } catch (error) {
        finish(
          error instanceof Error
            ? error
            : new Error('Could not send report data to the export worker.'),
        );
      }
    });
  }

  /** Served from the host app's `/mesix-reporting` assets folder, not from the library bundle URL. */
  private workerHref(): string {
    const base = typeof document !== 'undefined' ? document.baseURI : 'http://localhost/';
    return new URL('mesix-reporting/report-export.worker.js', base).href;
  }
}
