import { Inject, Injectable, InjectionToken, Optional } from '@angular/core';
import { ReportDefinition } from '../reporting.models';

export const MESIX_REPORT_DEFINITIONS = new InjectionToken<ReportDefinition[]>(
  'MESIX_REPORT_DEFINITIONS',
);

@Injectable({ providedIn: 'root' })
export class MesixReportRegistry {
  private readonly byId = new Map<string, ReportDefinition>();

  constructor(@Optional() @Inject(MESIX_REPORT_DEFINITIONS) definitions: ReportDefinition[] | null) {
    for (const definition of definitions || []) this.register(definition);
  }

  register(definition: ReportDefinition): void {
    if (!definition.id.trim()) throw new Error('A report definition requires a stable id.');
    if (this.byId.has(definition.id)) throw new Error(`Report "${definition.id}" is already registered.`);
    this.byId.set(definition.id, definition);
  }

  getAll(): ReportDefinition[] { return [...this.byId.values()]; }
  getById(id: string): ReportDefinition | undefined { return this.byId.get(id); }
}
