import { AfterViewInit, Component, ComponentRef, EventEmitter, Input, OnChanges, OnDestroy, Output, SimpleChanges, Type, ViewChild, ViewContainerRef } from '@angular/core';
import { Subscription } from 'rxjs';
import { ReportParameterWindowComponent } from './report-parameter-window.component';
import { ReportParameterWindowId } from './report-parameter-window-id';
import { ReportParameterWindowRegistry } from './report-parameter-window.registry';

@Component({ selector: 'mx-report-parameter-window-host', standalone: true, template: '<ng-container #host></ng-container>' })
export class ReportParameterWindowHostComponent implements AfterViewInit, OnChanges, OnDestroy {
  @Input({ required: true }) windowId!: ReportParameterWindowId;
  @Input() initialValues: Record<string, unknown> = {};
  @Output() readonly filtersChange = new EventEmitter<Record<string, unknown>>();
  @ViewChild('host', { read: ViewContainerRef }) private host?: ViewContainerRef;
  private ready = false;
  private componentRef?: ComponentRef<ReportParameterWindowComponent>;
  private componentType?: Type<ReportParameterWindowComponent>;
  private filtersSubscription?: Subscription;

  constructor(private registry: ReportParameterWindowRegistry) {}
  ngAfterViewInit(): void {
    this.ready = true;
    this.render();
  }

  ngOnChanges(changes: SimpleChanges): void {
    if (!this.ready || (!changes['windowId'] && !changes['initialValues'])) return;
    this.render(changes['windowId'] !== undefined);
  }

  ngOnDestroy(): void {
    this.filtersSubscription?.unsubscribe();
  }

  private render(recreate = false): void {
    if (!this.host || !this.windowId) return;
    const component: Type<ReportParameterWindowComponent> = this.registry.resolve(this.windowId);
    if (!recreate && this.componentRef && this.componentType === component) {
      // Filter components emit values while initializing. Updating the input in place prevents
      // that emission from destroying and recreating the component in a feedback loop.
      this.componentRef.setInput('initialValues', this.initialValues);
      return;
    }

    this.filtersSubscription?.unsubscribe();
    this.host.clear();
    this.componentType = component;
    this.componentRef = this.host.createComponent(component);
    this.componentRef.setInput('initialValues', this.initialValues);
    this.filtersSubscription = this.componentRef.instance.filtersChange.subscribe((filters) =>
      this.filtersChange.emit(filters),
    );
  }
}
